import random
random.seed(77)
draws = [(set(random.sample(range(1, 70), 5)), random.randint(1, 26)) for _ in range(60)]
last_w = {}
last_r = {}
for i, (w, r) in enumerate(draws):
    for n in w:
        last_w[n] = i
    last_r[r] = i
print('SIMULATED gaps (fixed seed, teaching only):')
print('longest white-ball gap:', max(59 - last_w.get(n, -1) for n in range(1, 70)))
print('longest Powerball gap:', max(59 - last_r.get(n, -1) for n in range(1, 27)))
print('expected gap: white about 13.8 draws, Powerball 26 draws')

def check(white, red):
    return len(white) == 5 and len(set(white)) == 5 and all(1 <= n <= 69 for n in white) and 1 <= red <= 26
samples = [([10, 33, 41, 47, 56], 10, 'record drawing format example'), ([10, 10, 41, 47, 56], 10, 'repeat, invalid'), ([10, 33, 41, 47, 99], 10, 'out of range, invalid')]
print('FORMAT-EXAMPLE checks (examples only, not a draw archive):')
for w, r, note in samples:
    print(w, r, 'valid format:', check(w, r), '-', note)
